<article class="article-page"><header class="container reveal"><span class="eyebrow"><?= e(localized($article,'category')) ?> · <?= e(date('d M Y',strtotime($article['published_at']))) ?></span><h1><?= e(localized($article,'title')) ?></h1><p><?= e(localized($article,'excerpt')) ?></p></header><div class="container article-image parallax-image"><img src="<?= e(image_url($article['image'])) ?>" alt="<?= e(localized($article,'title')) ?>"></div><div class="container prose article-body"><?php foreach(preg_split('/\R{2,}/', localized($article,'content')) ?: [] as $paragraph): ?><p><?= nl2br(e($paragraph)) ?></p><?php endforeach; ?><a class="text-link" href="<?= e(url('news')) ?>">← <?= e(tr('Kembali ke berita','Back to news')) ?></a></div></article>

<?php if($relatedArticles): ?><section class="section soft related-section"><div class="container section-head inline reveal"><div><span class="eyebrow"><?= e(tr('Bacaan Selanjutnya','Continue Reading')) ?></span><h2><?= e(tr('Wawasan terkait untuk Anda.','Related insights for you.')) ?></h2></div></div><div class="container news-grid stagger"><?php foreach($relatedArticles as $related): ?><article class="news-card"><a class="news-image" href="<?= e(url('news/'.$related['slug'])) ?>"><img src="<?= e(image_url($related['image'])) ?>" alt="<?= e(localized($related,'title')) ?>" loading="lazy"></a><div><span><?= e(localized($related,'category')) ?></span><h3><a href="<?= e(url('news/'.$related['slug'])) ?>"><?= e(localized($related,'title')) ?></a></h3><p><?= e(localized($related,'excerpt')) ?></p></div></article><?php endforeach; ?></div></section><?php endif; ?>
